let ranges: Int32Array | undefined;

/** The index of the range holding `codePoint` in the 4-wide table, or -1. */
function findRanges(codePoint: number): number {
  ranges ??= Int32Array.from(rangesData());
  let low = 0;
  let high = ranges.length / 4 - 1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    const at = middle * 4;
    if (codePoint < (ranges[at] as number)) high = middle - 1;
    else if (codePoint > (ranges[at + 1] as number)) low = middle + 1;
    else return at;
  }
  return -1;
}

